import static functions.MethodInvokeTest_checkInjectedInvoker;

// ------------------------------------------------------------------
// 1️⃣  Import / declare the classes you’re testing
// ------------------------------------------------------------------
class MyExpectedClass { /* … */ }

// ------------------------------------------------------------------
// 2️⃣  The CSM instance you want to inspect
// ------------------------------------------------------------------
CSM csmInstance = new CSM();          // ← replace with your real ctor / factory

// ------------------------------------------------------------------
// 3️⃣  The unit‑test itself
