@Test
void testCallerSensitiveInvokerIsCorrect() {
    // The helper expects *string* representations of the objects.
    // In practice you can just pass the objects themselves – the
    // underlying implementation will call .toString() for you.
    Object result = MethodInvokeTest_checkInjectedInvoker(
            csmInstance,          // the CSM instance under test
            MyExpectedClass.class // the class we expect to be injected
    );

    // The helper returns a Boolean (or a value that can be cast to Boolean).
    // If the check fails, the helper will return `false` (or throw an
    // exception – adjust your test accordingly).
